function interpolate(raw, params={}) { return String(raw).replace(/\{(\w+)\}/g, (_m,key)=>params[key] == null ? `{${key}}` : String(params[key])); }
function payload(response) { return response?.data || response || {}; }
async function callMerchants(action, body={}) {
  const data = payload(await base44.functions.invoke("getFounderControlCenter", { view:"merchants", action, ...body }));
  if (data?.ok === false) throw Object.assign(new Error(data.error || "merchant_portfolio_operation_failed"), { data });
  return data;
}
function flag(country) { const code=String(country||"").toUpperCase(); return /^[A-Z]{2}$/.test(code) ? [...code].map(char=>String.fromCodePoint(127397+char.charCodeAt(0))).join("") : "🌍"; }
function humanize(value) { return String(value||"").replaceAll("_"," ").replace(/\b\w/g,char=>char.toUpperCase()); }
function moneyMinor(value, currency="EUR", lang="en") { return Number.isFinite(Number(value)) ? new Intl.NumberFormat(lang,{style:"currency",currency,maximumFractionDigits:0}).format(Number(value)/100) : "—"; }
function numberValue(value, lang="en") { return Number.isFinite(Number(value)) ? new Intl.NumberFormat(lang,{maximumFractionDigits:1}).format(Number(value)) : "—"; }
function dateValue(value, lang="en") { const parsed=Date.parse(String(value||"")); return Number.isFinite(parsed) ? new Intl.DateTimeFormat(lang,{dateStyle:"medium",timeStyle:"short"}).format(parsed) : "—"; }
function formatKpi(kpi, lang) {
  if (kpi?.value == null || kpi?.status === "UNAVAILABLE") return "—";
  if (String(kpi.unit).startsWith("EUR_minor")) return moneyMinor(kpi.value,"EUR",lang);
  if (kpi.unit === "basis_points") return `${numberValue(Number(kpi.value)/100,lang)}%`;
  if (kpi.unit === "percent") return `${numberValue(kpi.value,lang)}%`;
  return numberValue(kpi.value,lang);
}
function kpiContextLine(kpi, lang) {
  const context=kpi?.context||{};
  if (kpi?.key==="total_merchants" || kpi?.key==="new_merchants") return context.new_this_month!=null ? `+${context.new_this_month} this month` : "This month";
  if (kpi?.key==="active_merchants") return context.percent_of_total!=null ? `${numberValue(context.percent_of_total,lang)}% of total` : "—";
  if (kpi?.key==="average_payment_cost") return context.annual_cost_minor ? `${moneyMinor(context.annual_cost_minor,"EUR",lang)}/year` : "Observed merchants only";
  if (kpi?.key==="potential_savings") return context.average_pct!=null ? `${numberValue(context.average_pct,lang)}% average · modeled` : "Modeled · never verified here";
  if (kpi?.key==="cambra_revenue") return context.collected_this_month_minor!=null ? `+${moneyMinor(context.collected_this_month_minor,"EUR",lang)} this month · collected` : "Collected revenue";
  if (kpi?.key==="recover_active") return context.modeled_savings_in_progress_minor!=null ? `${moneyMinor(context.modeled_savings_in_progress_minor,"EUR",lang)} modeled in progress` : "—";
  if (kpi?.key==="needs_attention") return `${context.approvals||0} approvals · ${context.incidents||0} incidents`;
  if (kpi?.key==="average_data_confidence") return `${context.high_confidence_merchants||0}/${context.measured_merchants||0} high confidence`;
  return kpi?.truth_class || "—";
}
function truthTone(value) { const key=String(value||"").toLowerCase(); return key==="verified"||key==="observed"?"border-emerald-500/25 bg-emerald-500/[.07] text-emerald-600":key==="modeled"||key==="estimated"?"border-amber-500/25 bg-amber-500/[.07] text-amber-600":"border-border bg-secondary/40 text-muted-foreground"; }
function TruthBadge({value}) { return <span className={`inline-flex rounded-full border px-2 py-0.5 text-[9px] font-black uppercase tracking-wide ${truthTone(value)}`}>{humanize(value||"unknown")}</span>; }
function Loading({label}) { return <div className="flex min-h-40 items-center justify-center gap-2 text-xs text-muted-foreground"><Loader2 size={15} className="animate-spin"/>{label}</div>; }
function ErrorNotice({error,onRetry=null,t}) { if(!error)return null;return <div role="alert" className="flex items-start gap-3 rounded-2xl border border-rose-500/25 bg-rose-500/[.07] p-4 text-xs text-rose-600"><AlertTriangle size={16}/><div className="min-w-0 flex-1"><p className="font-bold">{humanize(error)}</p></div>{onRetry&&<button onClick={onRetry} className="rounded-lg border border-rose-500/25 px-3 py-1.5 font-bold">{t("retry")}</button>}</div>; }

function AskCambraDrawer({state,setState,t}) {
  const [question,setQuestion]=useState("");
  const [messages,setMessages]=useState([]);
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");
  const context=state?.context||{context_level:"SEGMENT"};
  const ask=async(value=question)=>{const prompt=String(value||"").trim();if(!prompt||loading)return;const conversationHistory=messages.slice(-12).map(message=>({role:message.role,content:String(message.text||"").slice(0,2000)}));setMessages(rows=>[...rows,{role:"user",text:prompt}]);setQuestion("");setLoading(true);setError("");try{const response=await base44.functions.invoke("copilotChat",{question:prompt,pageTitle:"Founder/Admin · Merchants",pageDescription:"Canonical merchant portfolio intelligence.",nextStep:"Inspect evidence or use an existing governed action.",context_scope:"MERCHANT_PORTFOLIO",merchant_context:context,conversation_history:conversationHistory});const data=payload(response);setMessages(rows=>[...rows,{role:"assistant",text:data.answer||t("chat_error")}])}catch(cause){setError(cause?.message||t("chat_error"))}finally{setLoading(false)}};
  useEffect(()=>{if(state?.prompt){ask(state.prompt);setState(current=>current?{...current,prompt:""}:current)}},[state?.prompt]);
  if(!state?.open)return null;
  return <div className="fixed inset-0 z-[100] bg-black/35 p-3 backdrop-blur-sm" onClick={()=>setState(current=>({...current,open:false}))}><aside className="ml-auto flex h-full w-full max-w-lg flex-col overflow-hidden rounded-3xl border bg-card shadow-2xl" onClick={event=>event.stopPropagation()}><header className="flex items-start justify-between border-b p-5"><div><p className="flex items-center gap-2 text-base font-black"><Bot size={17}/>{t("chat_title")}</p><p className="mt-1 text-[10px] text-muted-foreground">{t("chat_scope",{scope:state.label||"Portfolio"})}</p></div><button aria-label={t("close")} onClick={()=>setState(current=>({...current,open:false}))} className="rounded-full border p-2"><X size={14}/></button></header><div className="flex-1 space-y-3 overflow-y-auto p-5">{!messages.length&&<div className="rounded-2xl bg-secondary/50 p-4 text-xs leading-5">{t("chat_intro")}</div>}{messages.map((message,index)=><div key={`${message.role}-${index}`} className={`rounded-2xl p-3 text-xs leading-5 ${message.role==="user"?"ml-9 bg-foreground text-background":"mr-9 bg-secondary"}`}>{message.text}</div>)}{loading&&<Loader2 size={16} className="animate-spin"/>}{error&&<ErrorNotice error={error} t={t}/>}</div><footer className="border-t p-4"><div className="mb-2 flex flex-wrap gap-1.5">{(state.suggestions||[]).map(prompt=><button key={prompt} disabled={loading} onClick={()=>ask(prompt)} className="rounded-full border px-2.5 py-1 text-[9px] font-bold text-muted-foreground hover:text-foreground">{prompt}</button>)}</div><textarea value={question} onChange={event=>setQuestion(event.target.value)} onKeyDown={event=>{if(event.key==="Enter"&&!event.shiftKey){event.preventDefault();ask()}}} placeholder={t("chat_placeholder")} className="min-h-20 w-full resize-none rounded-xl border bg-background p-3 text-xs"/><button disabled={loading||!question.trim()} onClick={()=>ask()} className="mt-2 h-10 w-full rounded-xl bg-foreground text-xs font-black text-background disabled:opacity-40">{t("ask")}</button></footer></aside></div>;
}

function KpiCard({kpi,open,onClick,lang}) {
  return <button onClick={onClick} aria-expanded={open} className={`min-h-32 rounded-2xl border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:shadow-md ${open?"border-foreground/40 ring-1 ring-foreground/10":"border-border/60"}`}><div className="flex items-start justify-between gap-2"><p className="text-[10px] font-black uppercase tracking-[.13em] text-muted-foreground">{KPI_TRANSLATIONS[lang]?.[kpi.key]||KPI_LABELS[kpi.key]||kpi.label}</p><TruthBadge value={kpi.truth_class}/></div><p className="mt-4 text-2xl font-black tracking-tight tabular-nums">{formatKpi(kpi,lang)}</p><div className="mt-2 flex items-end justify-between gap-2"><p className="text-[10px] leading-4 text-muted-foreground">{kpi.status==="PARTIAL"?"Partial · ":""}{kpiContextLine(kpi,lang)}</p><ChevronDown size={14} className={`shrink-0 transition ${open?"rotate-180":""}`}/></div></button>;
}

function MiniMerchant({merchant,lang,onOpen}) { return <button onClick={()=>onOpen(merchant.id)} className="flex w-full items-center justify-between gap-3 rounded-xl border p-3 text-left hover:bg-secondary/30"><div className="min-w-0"><p className="truncate text-xs font-black">{merchant.trading_name}</p><p className="mt-1 text-[9px] text-muted-foreground">{flag(merchant.country)} {merchant.country||"—"} · {humanize(merchant.merchant_status)}</p></div><div className="text-right"><p className="text-xs font-black">{merchant.potential_savings?.pct==null?"—":`${numberValue(merchant.potential_savings.pct,lang)}%`}</p><p className="text-[9px] text-muted-foreground">{moneyMinor(merchant.potential_savings?.value_minor,"EUR",lang)}/yr</p></div></button>; }

function KpiBreakdown({detail,lang,t,onOpenMerchant}) {
  const breakdown=detail?.breakdown||{};
  return <div className="space-y-6"><div className="grid gap-5 lg:grid-cols-2"><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">{t("top_merchants")}</p><div className="space-y-2">{(breakdown.top_merchants||[]).slice(0,10).map(row=><MiniMerchant key={row.id} merchant={row} lang={lang} onOpen={onOpenMerchant}/>)}{!breakdown.top_merchants?.length&&<p className="text-xs text-muted-foreground">{t("no_evidence")}</p>}</div></section><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">{t("by_country")}</p><div className="space-y-2">{(breakdown.by_country||[]).map(row=><div key={row.country} className="flex justify-between rounded-lg border p-3 text-xs"><span>{flag(row.country)} {row.country}</span><b>{numberValue(row.count,lang)}</b></div>)}</div></section></div>
    {breakdown.potential_savings&&<section className="space-y-3"><p className="text-[10px] font-black uppercase text-muted-foreground">Potential savings intelligence · modeled</p><div className="grid gap-3 lg:grid-cols-3"><div className="rounded-xl border p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Confidence</p><KeyValueGrid data={breakdown.potential_savings.confidence} lang={lang}/></div><div className="rounded-xl border p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Recover coverage</p><KeyValueGrid data={breakdown.potential_savings.recover_coverage} lang={lang}/></div><div className="rounded-xl border p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Concentration</p><KeyValueGrid data={breakdown.potential_savings.concentration} lang={lang}/></div></div><div className="grid gap-4 lg:grid-cols-2"><ObjectRows title="Modeled savings by country" rows={breakdown.potential_savings.by_country} lang={lang}/><ObjectRows title="Linked modeled savings by PSP" rows={breakdown.potential_savings.by_psp} lang={lang}/></div><ObjectRows title="Modeled trend" rows={breakdown.potential_savings.trend} lang={lang}/>{breakdown.potential_savings.psp_attribution_boundary&&<p className="rounded-xl border border-amber-500/25 p-3 text-[10px] text-muted-foreground">{breakdown.potential_savings.psp_attribution_boundary}</p>}</section>}
    {breakdown.revenue&&<section className="space-y-3"><p className="text-[10px] font-black uppercase text-muted-foreground">Earned · Invoiced · Collected · Outstanding</p><KeyValueGrid data={breakdown.revenue.totals} lang={lang}/><ObjectRows title="Revenue evolution" rows={breakdown.revenue.evolution} lang={lang}/><ObjectRows title="Merchant contribution" rows={breakdown.revenue.merchant_contribution} lang={lang}/></section>}
    {breakdown.data_confidence&&<section className="space-y-3"><p className="text-[10px] font-black uppercase text-muted-foreground">Data confidence remediation</p><KeyValueGrid data={breakdown.data_confidence.causes} lang={lang}/><ObjectRows title="Remediation queue" rows={breakdown.data_confidence.remediation_queue} lang={lang}/></section>}
    {breakdown.direct_founder_decisions&&<section className="space-y-3"><div className="flex items-center justify-between"><p className="text-[10px] font-black uppercase text-muted-foreground">Direct Founder decisions</p><Link to="/admin/approvals" className="rounded-lg border px-3 py-2 text-[10px] font-bold">{t("approvals_link")}</Link></div><ObjectRows title="Approvals" rows={breakdown.direct_founder_decisions.approvals} lang={lang}/><ObjectRows title="Incidents" rows={breakdown.direct_founder_decisions.incidents} lang={lang}/></section>}
  </div>;
}

function KpiDrilldown({detail,loading,error,kpi,t,lang,onAsk,onOpenMerchant,onExport}) {
  const [tab,setTab]=useState("overview");
  const tabs=[["overview",t("overview")],["breakdown",t("breakdown")],["insights",t("insights")],["recommendations",t("recommendations")],["actions",t("actions")]];
  if(loading)return <Loading label={t("loading_detail")}/>;
  if(error)return <ErrorNotice error={error} t={t}/>;
  if(!detail)return null;
  return <div className="col-span-full rounded-2xl border bg-card p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-1">{tabs.map(([key,label])=><button key={key} onClick={()=>setTab(key)} className={`rounded-lg px-3 py-2 text-[10px] font-bold ${tab===key?"bg-foreground text-background":"bg-secondary text-muted-foreground"}`}>{label}</button>)}</div><button onClick={()=>onAsk({context_level:"KPI",kpi_key:kpi.key},KPI_TRANSLATIONS[lang]?.[kpi.key]||kpi.label,["Top merchants","Explain this","Find anomalies","What should I do?","Compare countries"])} className="inline-flex h-9 items-center gap-1.5 rounded-lg border px-3 text-xs font-bold"><Bot size={13}/>{t("ask")}</button></div><div className="mt-5 min-h-24">
    {tab==="overview"&&<div className="grid gap-3 md:grid-cols-3"><div className="rounded-xl bg-secondary/40 p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Value</p><p className="mt-2 text-xl font-black">{formatKpi(detail.kpi||kpi,lang)}</p></div><div className="rounded-xl bg-secondary/40 p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Truth</p><div className="mt-2"><TruthBadge value={detail.overview?.truth_class}/></div></div><div className="rounded-xl bg-secondary/40 p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">Claim boundary</p><p className="mt-2 text-[10px] leading-4 text-muted-foreground">{detail.overview?.claim_boundary||t("no_evidence")}</p></div></div>}
    {tab==="breakdown"&&<KpiBreakdown detail={detail} lang={lang} t={t} onOpenMerchant={onOpenMerchant}/>} 
    {tab==="insights"&&<BulletList rows={detail.insights} empty={t("no_evidence")}/>} {tab==="recommendations"&&<BulletList rows={detail.recommendations} empty={t("no_evidence")}/>} {tab==="actions"&&<div className="flex flex-wrap gap-2"><button onClick={onExport} className="inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold"><ArrowDownToLine size={13}/>{t("export")}</button><button onClick={()=>onAsk({context_level:"KPI",kpi_key:kpi.key},kpi.label,["What should I do?"])} className="inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-bold"><Bot size={13}/>{t("ask")}</button></div>}
  </div><p className="mt-4 text-[9px] text-muted-foreground">{t("unknown_values_last")}</p></div>;
}

function BulletList({rows=[],empty}) { return rows?.length?<ul className="space-y-2">{rows.map((row,index)=><li key={`${index}-${String(row)}`} className="flex gap-2 text-xs leading-5"><Check size={13} className="mt-1 shrink-0 text-emerald-500"/><span>{typeof row==="string"?row:JSON.stringify(row)}</span></li>)}</ul>:<p className="text-xs text-muted-foreground">{empty}</p>; }

function MultiFilter({label,options=[],value=[],onChange,render=(item)=>humanize(item),t}) {
  const selected=Array.isArray(value)?value:[];
  return <details className="relative"><summary className="flex h-10 cursor-pointer list-none items-center justify-between rounded-xl border bg-background px-3 text-xs"><span className="truncate">{label}: <b>{selected.length?selected.map(render).join(", "):t("any")}</b></span><ChevronDown size={13}/></summary><div className="absolute left-0 top-11 z-30 max-h-64 w-full min-w-52 overflow-y-auto rounded-xl border bg-card p-2 shadow-xl">{options.length?options.map(option=>{const key=String(option);const checked=selected.includes(option);return <label key={key} className="flex cursor-pointer items-center gap-2 rounded-lg px-2 py-2 text-xs hover:bg-secondary"><input type="checkbox" checked={checked} onChange={()=>onChange(checked?selected.filter(item=>item!==option):[...selected,option])}/><span className="truncate">{render(option)}</span></label>}):<p className="p-2 text-[10px] text-muted-foreground">{t("no_evidence")}</p>}</div></details>;
}
function RangeFilter({label,minKey,maxKey,filters,setFilters,t,step="any"}) {
  return <div className="rounded-xl border p-3"><p className="mb-2 text-[10px] font-black uppercase tracking-wide text-muted-foreground">{label}</p><div className="grid grid-cols-2 gap-2"><label className="text-[9px] text-muted-foreground">{t("minimum")}<input type="number" min="0" step={step} value={filters[minKey]??""} onChange={event=>setFilters(current=>({...current,[minKey]:event.target.value===""?undefined:Number(event.target.value)}))} className="mt-1 h-8 w-full rounded-lg border bg-background px-2 text-xs text-foreground"/></label><label className="text-[9px] text-muted-foreground">{t("maximum")}<input type="number" min="0" step={step} value={filters[maxKey]??""} onChange={event=>setFilters(current=>({...current,[maxKey]:event.target.value===""?undefined:Number(event.target.value)}))} className="mt-1 h-8 w-full rounded-lg border bg-background px-2 text-xs text-foreground"/></label></div></div>;
}
function DateRange({label,fromKey,toKey,filters,setFilters,t}) { return <div className="rounded-xl border p-3"><p className="mb-2 text-[10px] font-black uppercase tracking-wide text-muted-foreground">{label}</p><div className="grid grid-cols-2 gap-2"><label className="text-[9px] text-muted-foreground">{t("from")}<input type="date" value={filters[fromKey]||""} onChange={event=>setFilters(current=>({...current,[fromKey]:event.target.value||undefined}))} className="mt-1 h-8 w-full rounded-lg border bg-background px-2 text-xs text-foreground"/></label><label className="text-[9px] text-muted-foreground">{t("to")}<input type="date" value={filters[toKey]||""} onChange={event=>setFilters(current=>({...current,[toKey]:event.target.value||undefined}))} className="mt-1 h-8 w-full rounded-lg border bg-background px-2 text-xs text-foreground"/></label></div></div>; }

function FilterPanel({options,filters,setFilters,t}) {
  const set=(key,value)=>setFilters(current=>({...current,[key]:value?.length?value:undefined}));
  return <div className="rounded-2xl border bg-card p-4"><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><MultiFilter label={t("status")} options={options.status||[]} value={filters.status} onChange={value=>set("status",value)} t={t}/><MultiFilter label={t("country")} options={options.country||[]} value={filters.country} onChange={value=>set("country",value)} render={value=>`${flag(value)} ${value}`} t={t}/><MultiFilter label={t("psp")} options={options.psp||[]} value={filters.psp} onChange={value=>set("psp",value)} t={t}/><MultiFilter label={t("recover_status")} options={options.recover_status||[]} value={filters.recover_status} onChange={value=>set("recover_status",value)} t={t}/><MultiFilter label={t("current_phase")} options={options.current_phase||[]} value={filters.current_phase} onChange={value=>set("current_phase",value)} t={t}/><MultiFilter label={t("data_source")} options={options.data_source||[]} value={filters.data_source} onChange={value=>set("data_source",value)} t={t}/><label className="flex h-10 items-center justify-between rounded-xl border px-3 text-xs"><span>{t("attention")}</span><select value={filters.needs_attention===true?"yes":filters.needs_attention===false?"no":""} onChange={event=>setFilters(current=>({...current,needs_attention:event.target.value==="yes"?true:event.target.value==="no"?false:undefined}))} className="bg-transparent font-bold outline-none"><option value="">{t("any")}</option><option value="yes">{t("yes")}</option><option value="no">{t("no")}</option></select></label></div><div className="mt-3 grid gap-3 md:grid-cols-2 xl:grid-cols-4"><RangeFilter label={`${t("payment_volume")} (€)`} minKey="payment_volume_min_eur" maxKey="payment_volume_max_eur" filters={filters} setFilters={setFilters} t={t}/><RangeFilter label={t("payment_cost")} minKey="payment_cost_min_pct" maxKey="payment_cost_max_pct" filters={filters} setFilters={setFilters} t={t} step="0.01"/><RangeFilter label={t("potential_savings_filter")} minKey="potential_savings_min_pct" maxKey="potential_savings_max_pct" filters={filters} setFilters={setFilters} t={t} step="0.1"/><RangeFilter label={`${t("verified_savings")} (€)`} minKey="verified_savings_min_eur" maxKey="verified_savings_max_eur" filters={filters} setFilters={setFilters} t={t}/><RangeFilter label={`${t("data_confidence")} %`} minKey="data_confidence_min" maxKey="data_confidence_max" filters={filters} setFilters={setFilters} t={t} step="1"/><DateRange label={t("joined_date")} fromKey="joined_from" toKey="joined_to" filters={filters} setFilters={setFilters} t={t}/><DateRange label={t("last_activity")} fromKey="last_activity_from" toKey="last_activity_to" filters={filters} setFilters={setFilters} t={t}/></div><div className="mt-3 flex justify-end"><button onClick={()=>setFilters({})} className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-[10px] font-bold"><X size={12}/>{t("clear")}</button></div></div>;
}

function SmartValue({name,value,lang}) {
  if(value===null||value===undefined||value==="")return <span className="text-muted-foreground">—</span>;
  const key=String(name||"").toLowerCase();
  if(typeof value==="boolean")return <span>{value?"Yes":"No"}</span>;
  if(typeof value==="number") {
    if(key.includes("minor"))return <span>{moneyMinor(value,"EUR",lang)}</span>;
    if(key.endsWith("_bps")||key==="bps")return <span>{numberValue(value/100,lang)}%</span>;
    if(key.includes("pct")||key.includes("percent")||key.includes("confidence")||key.includes("score"))return <span>{numberValue(value,lang)}{key.includes("pct")||key.includes("percent")||key.includes("confidence")?"%":""}</span>;
    return <span>{numberValue(value,lang)}</span>;
  }
  if((key.includes("date")||key.endsWith("_at")||key==="month")&&Number.isFinite(Date.parse(String(value))))return <span>{dateValue(value,lang)}</span>;
  if(typeof value==="string")return <span className="break-words">{value}</span>;
  return <span className="text-muted-foreground">{humanize(String(value))}</span>;
}
function KeyValueGrid({data,lang,omit=[]}) {
  const entries=Object.entries(data||{}).filter(([key,value])=>!omit.includes(key)&&!Array.isArray(value)&&!(value&&typeof value==="object"));
  if(!entries.length)return null;
  return <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{entries.map(([key,value])=><div key={key} className="rounded-xl border bg-background p-3"><p className="text-[9px] font-bold uppercase tracking-wide text-muted-foreground">{humanize(key)}</p><p className="mt-1 text-xs font-semibold"><SmartValue name={key} value={value} lang={lang}/></p></div>)}</div>;
}
function NestedValue({name,value,lang,depth=0}) {
  if(value===null||value===undefined||typeof value!=="object")return <SmartValue name={name} value={value} lang={lang}/>;
  if(depth>=2)return <span className="text-[9px] text-muted-foreground">Evidence available · open its canonical domain for full depth</span>;
  if(Array.isArray(value)) {
    if(!value.length)return <span className="text-[9px] text-muted-foreground">None recorded</span>;
    if(value.every(item=>item===null||typeof item!=="object"))return <div className="flex flex-wrap gap-1">{value.slice(0,30).map((item,index)=><span key={`${item}-${index}`} className="rounded-full border px-2 py-0.5 text-[9px]">{String(item)}</span>)}</div>;
    return <div className="space-y-2">{value.slice(0,20).map((item,index)=><div key={item?.id||index} className="rounded-lg border bg-secondary/20 p-2"><NestedValue name={`${name} ${index+1}`} value={item} lang={lang} depth={depth+1}/></div>)}{value.length>20&&<p className="text-[9px] text-muted-foreground">20 / {value.length} items shown</p>}</div>;
  }
  return <div className="grid gap-2 sm:grid-cols-2">{Object.entries(value).slice(0,20).map(([key,nested])=><div key={key} className="min-w-0"><p className="text-[8px] font-bold uppercase text-muted-foreground">{humanize(key)}</p><div className="mt-0.5 text-[10px] leading-4"><NestedValue name={key} value={nested} lang={lang} depth={depth+1}/></div></div>)}</div>;
}
function ObjectRows({title,rows=[],lang,technical=false}) {
  const safe=Array.isArray(rows)?rows:[];
  if(!safe.length)return null;
  return <section><p className="mb-2 text-[10px] font-black uppercase tracking-[.12em] text-muted-foreground">{humanize(title)}</p><div className="space-y-2">{safe.slice(0,100).map((row,index)=>{if(row===null||typeof row!=="object")return <div key={index} className="rounded-xl border p-3 text-xs"><SmartValue name={title} value={row} lang={lang}/></div>;const entries=Object.entries(row);const primitives=entries.filter(([,value])=>value===null||["string","number","boolean"].includes(typeof value)).slice(0,technical?18:10);const nested=entries.filter(([,value])=>value&&typeof value==="object").slice(0,technical?8:4);return <article key={row.id||`${title}-${index}`} className="rounded-xl border bg-background p-3"><div className="grid gap-x-4 gap-y-2 sm:grid-cols-2 xl:grid-cols-3">{primitives.map(([key,value])=><div key={key} className="min-w-0"><p className="text-[8px] font-bold uppercase text-muted-foreground">{humanize(key)}</p><p className="mt-0.5 text-[10px] leading-4"><SmartValue name={key} value={value} lang={lang}/></p></div>)}</div>{nested.length>0&&<div className="mt-3 grid gap-3 lg:grid-cols-2">{nested.map(([key,value])=><details key={key} className="rounded-lg border bg-secondary/10 p-2"><summary className="cursor-pointer list-none text-[8px] font-bold uppercase text-muted-foreground">{humanize(key)}<ChevronDown size={10} className="float-right"/></summary><div className="mt-2"><NestedValue name={key} value={value} lang={lang}/></div></details>)}</div>}</article>})}</div>{safe.length>100&&<p className="mt-2 text-[9px] text-muted-foreground">100 / {safe.length} rows shown</p>}</section>;
}
function MerchantSummaryMetrics({row,lang}) {
  if(!row)return null;
  const coverage=row.evidence?.source_coverage||{};
  const unavailable=(key,value)=>coverage[key]==="UNAVAILABLE"?"Unavailable":value;
  const metrics=[
    ["Payment Volume",row.payment_volume?moneyMinor(row.payment_volume.value_minor,"EUR",lang):"—",row.payment_volume?.truth_class],
    ["Payment Cost",row.payment_cost?`${numberValue(row.payment_cost.bps/100,lang)}% · ${moneyMinor(row.payment_cost.annual_cost_minor,"EUR",lang)}/yr`:"—",row.payment_cost?.truth_class],
    ["Potential Savings",row.potential_savings?`${numberValue(row.potential_savings.pct,lang)}% · ${moneyMinor(row.potential_savings.value_minor,"EUR",lang)}/yr`:"—",row.potential_savings?.truth_class],
    ["Verified Savings",unavailable("verified_savings",moneyMinor(row.verified_savings?.value_minor,"EUR",lang)),row.verified_savings?.truth_class],
    ["CAMBRA Revenue",unavailable("cambra_revenue",moneyMinor(row.cambra_revenue?.collected_minor,"EUR",lang)),row.cambra_revenue?.truth_class],
    ["Current Phase",humanize(row.current_phase||"unknown"),"observed"],
    ["Recover Status",humanize(row.recover?.status||"not activated"),"observed"],
    ["Data Confidence",row.data_confidence==null?"—":`${numberValue(row.data_confidence,lang)}% · ${row.data_confidence_label}`,"observed"],
    ["Data Source",(row.data_sources||[]).length?(row.data_sources||[]).map(humanize).join(" + "):"—","observed"],
    ["Needs Attention",row.needs_attention==null?"Unavailable":numberValue(row.needs_attention,lang),row.attention_status],
    ["Joined CAMBRA",dateValue(row.joined_at,lang),"observed"],["Last Activity",dateValue(row.last_activity_at,lang),"observed"],
  ];
  return <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-5">{metrics.map(([label,value,truth])=><div key={label} className="rounded-xl border bg-background p-3"><p className="text-[8px] font-bold uppercase tracking-wide text-muted-foreground">{label}</p><p className="mt-1 text-xs font-black">{value}</p>{truth&&<div className="mt-2"><TruthBadge value={truth}/></div>}</div>)}</div>;
}

function blockMini(row,key,lang,t) {
  const potential=row.potential_savings;
  if(key==="overview")return `${row.payment_volume?moneyMinor(row.payment_volume.value_minor,"EUR",lang):"—"} volume · ${row.payment_cost?`${numberValue(row.payment_cost.bps/100,lang)}% cost`:"cost unknown"} · ${potential?.pct==null?"—":`${numberValue(potential.pct,lang)}%`} potential`;
  if(key==="payments_infrastructure")return `${row.psps?.join(" + ")||"PSP unknown"} · ${row.payment_volume?moneyMinor(row.payment_volume.value_minor,"EUR",lang):"volume unknown"}`;
  if(key==="analyzer_opportunities")return potential?`${numberValue(potential.pct,lang)}% · ${moneyMinor(potential.value_minor,"EUR",lang)} modeled potential`:t("not_analyzed");
  if(key==="recover_savings")return `${humanize(row.recover?.status||"not activated")} · ${moneyMinor(row.verified_savings?.value_minor,"EUR",lang)} verified`;
  if(key==="data_documents")return `${row.data_confidence==null?"—":`${numberValue(row.data_confidence,lang)}%`} confidence · ${(row.data_sources||[]).map(humanize).join(" + ")||"source unknown"}`;
  if(key==="cambra_activity")return `Updated ${dateValue(row.last_activity_at,lang)}`;
  if(key==="attention_approvals")return row.needs_attention==null?t("unavailable"):row.needs_attention?`${row.needs_attention} action(s) required`:`Nothing required ✓`;
  if(key==="company_contacts")return `${flag(row.country)} ${row.country||"Country unknown"} · Joined ${dateValue(row.joined_at,lang)}`;
  if(key==="billing_revenue")return row.evidence?.source_coverage?.cambra_revenue==="UNAVAILABLE"?t("unavailable"):`${moneyMinor(row.cambra_revenue?.collected_minor,"EUR",lang)} collected`;
  if(key==="communications")return `Last activity ${dateValue(row.last_activity_at,lang)}`;
  if(key==="technical_audit")return row.attention_breakdown?.incidents?`${row.attention_breakdown.incidents} direct incident(s)`:`Load current technical evidence`;
  return "Load current evidence";
}

function DependencyStrip({rows=[],t}) {
  if(!rows?.length)return null;
  const limited=rows.filter(row=>row.status!=="AVAILABLE");
  return <details className="mt-4 rounded-xl border bg-secondary/20 p-3"><summary className="cursor-pointer list-none text-[9px] font-black uppercase tracking-wide text-muted-foreground">{t("source_health")} · {limited.length?`${limited.length} limited`:t("up_to_date")}<ChevronDown size={12} className="float-right"/></summary><div className="mt-3 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{rows.map((row,index)=><div key={`${row.source||row.dependency?.source||"source"}-${index}`} className="flex items-center justify-between gap-2 rounded-lg border bg-background p-2 text-[9px]"><span className="truncate">{row.source||row.dependency?.source||"Source"}</span><TruthBadge value={row.status||row.dependency?.status}/></div>)}</div></details>;
}
function BlockContent({block,result,row,lang,t}) {
  if(block==="overview")return <MerchantSummaryMetrics row={result.summary||row} lang={lang}/>;
  const data=result?.data;
  if(!data)return <p className="text-xs text-muted-foreground">{t("no_evidence")}</p>;
  if(block==="payments_infrastructure")return <div className="space-y-5"><ObjectRows title="Integrations & connection health" rows={data.integrations} lang={lang}/>{data.profile&&<section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Payments profile</p><KeyValueGrid data={data.profile} lang={lang}/></section>}<ObjectRows title="Provider demand & volume" rows={data.demand_units} lang={lang}/><ObjectRows title="Observed effective rates" rows={data.verified_analyses} lang={lang}/></div>;
  if(block==="analyzer_opportunities")return <div className="space-y-5"><div className="grid grid-cols-4 gap-2 text-center text-[9px] font-bold"><div className="rounded-xl border p-3">Current Cost</div><div className="rounded-xl border p-3">Benchmark</div><div className="rounded-xl border p-3">Gap</div><div className="rounded-xl border p-3">Potential Saving</div></div>{data.latest_analysis&&<section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Latest Analyzer run</p><KeyValueGrid data={data.latest_analysis} lang={lang}/></section>}<ObjectRows title="Opportunities" rows={data.routing_opportunities} lang={lang}/><ObjectRows title="Analysis history" rows={data.analysis_history} lang={lang}/>{result.truth_boundary&&<p className="rounded-xl border border-amber-500/25 bg-amber-500/[.05] p-3 text-[10px] text-amber-600">{result.truth_boundary}</p>}</div>;
  if(block==="recover_savings")return <div className="space-y-5"><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Savings funnel</p><div className="grid grid-cols-2 gap-2 lg:grid-cols-4">{Object.entries(data.funnel||{}).map(([key,value])=><div key={key} className="rounded-xl border p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">{humanize(key)}</p><p className="mt-2 text-lg font-black">{moneyMinor(value,"EUR",lang)}</p><TruthBadge value={key.startsWith("verified")||key.startsWith("realized")?"verified":"modeled"}/></div>)}</div></section><ObjectRows title="Recover processes" rows={data.activations} lang={lang}/><ObjectRows title="Negotiations" rows={data.negotiations} lang={lang}/><ObjectRows title="Verification reports" rows={data.savings_reports} lang={lang}/><ObjectRows title="Mandates" rows={data.mandates} lang={lang}/><ObjectRows title="Migrations" rows={data.migrations} lang={lang}/>{result.truth_boundary&&<p className="rounded-xl border border-amber-500/25 bg-amber-500/[.05] p-3 text-[10px] text-amber-600">{result.truth_boundary}</p>}</div>;
  if(block==="data_documents")return <div className="space-y-5"><div className="rounded-2xl border bg-secondary/30 p-5"><p className="text-[9px] font-black uppercase text-muted-foreground">Data confidence</p><p className="mt-2 text-2xl font-black">{data.data_confidence==null?"—":`${numberValue(data.data_confidence,lang)}%`}</p></div><ObjectRows title="Connected data" rows={data.connected_data} lang={lang}/><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Documents</p><div className="space-y-2">{(data.documents||[]).map(doc=><article key={doc.id} className="flex items-center justify-between gap-3 rounded-xl border p-3"><div className="min-w-0"><p className="truncate text-xs font-bold">{doc.title||doc.file_name||"Document"}</p><p className="mt-1 text-[9px] text-muted-foreground">{humanize(doc.category)} · {dateValue(doc.uploaded_at,lang)} · {humanize(doc.review_status||"unknown")}</p></div>{doc.file_url&&<a href={doc.file_url} target="_blank" rel="noreferrer" className="rounded-lg border px-3 py-1.5 text-[9px] font-bold">View</a>}</article>)}{!data.documents?.length&&<p className="text-xs text-muted-foreground">{t("no_evidence")}</p>}</div></section><ObjectRows title="Statement imports" rows={data.statement_imports} lang={lang}/><ObjectRows title="Verified evidence" rows={data.verified_evidence} lang={lang}/>{data.missing_or_conflicting_data?.length>0&&<section className="rounded-xl border border-amber-500/25 bg-amber-500/[.05] p-4"><p className="text-[10px] font-black uppercase text-amber-600">Missing / conflicting data</p><BulletList rows={data.missing_or_conflicting_data} empty={t("no_evidence")}/></section>}</div>;
  if(block==="cambra_activity")return <div className="space-y-5"><ObjectRows title="Right now" rows={data.right_now} lang={lang}/><ObjectRows title="Timeline" rows={data.timeline} lang={lang}/></div>;
  if(block==="attention_approvals")return <div className="space-y-3">{data.map(item=><article key={`${item.type}-${item.id}`} className="rounded-xl border p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-xs font-black">{humanize(item.title||item.type)}</p><p className="mt-1 text-[10px] text-muted-foreground">{humanize(item.status)} · {item.risk_level?`Risk ${item.risk_level}`:humanize(item.severity||"")}</p></div><TruthBadge value={item.status}/></div>{item.why&&<p className="mt-3 text-xs leading-5">{Array.isArray(item.why)?item.why.join(" · "):item.why}</p>}{item.recommendation&&<p className="mt-2 text-[10px] text-muted-foreground"><b>{t("recommendations")}:</b> {item.recommendation}</p>}{item.type==="approval"&&<Link to="/admin/approvals" className="mt-3 inline-flex items-center gap-1 rounded-lg border px-3 py-2 text-[10px] font-bold"><ShieldCheck size={12}/>{t("approvals_link")}</Link>}</article>)}{!data.length&&<div className="rounded-xl border border-emerald-500/25 bg-emerald-500/[.05] p-4 text-xs text-emerald-600">Nothing required ✓</div>}</div>;
  if(block==="company_contacts")return <div className="grid gap-5 lg:grid-cols-2"><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Company</p><KeyValueGrid data={data.company} lang={lang}/></section><ObjectRows title="Contacts & CAMBRA users" rows={data.contacts} lang={lang}/></div>;
  if(block==="billing_revenue")return <div className="space-y-5"><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Earned · Invoiced · Collected · Outstanding</p><div className="grid grid-cols-2 gap-2 lg:grid-cols-4">{["earned_minor","invoiced_minor","collected_minor","outstanding_minor"].map(key=><div key={key} className="rounded-xl border p-4"><p className="text-[9px] font-bold uppercase text-muted-foreground">{humanize(key.replace("_minor",""))}</p><p className="mt-2 text-lg font-black">{moneyMinor(data.revenue?.[key],data.revenue?.currency||"EUR",lang)}</p><TruthBadge value={data.revenue?.truth?.[key.replace("_minor","")]}/></div>)}</div></section><ObjectRows title="Invoice history" rows={data.invoices} lang={lang}/><ObjectRows title="Payment events & reconciliation" rows={data.payment_events} lang={lang}/><ObjectRows title="Savings reports" rows={data.savings_reports} lang={lang}/>{data.unit_economics&&<section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Unit economics</p><KeyValueGrid data={data.unit_economics} lang={lang}/></section>}</div>;
  if(block==="contracts_legal")return <div className="space-y-5"><ObjectRows title="Recover mandates" rows={data.mandates} lang={lang}/><ObjectRows title="Merchant contracts" rows={data.contracts} lang={lang}/><ObjectRows title="Contract documents" rows={data.contract_documents} lang={lang}/><section><p className="mb-2 text-[10px] font-black uppercase text-muted-foreground">Merchant legal identity</p><KeyValueGrid data={data.merchant_legal_identity} lang={lang}/></section></div>;
  if(block==="communications")return <div className="space-y-5"><ObjectRows title="Merchant ↔ CAMBRA" rows={data.merchant_cambra} lang={lang}/><ObjectRows title="CAMBRA ↔ Providers" rows={data.cambra_providers} lang={lang}/><ObjectRows title="Messages" rows={data.messages} lang={lang}/>{result.scope_boundary&&<p className="rounded-xl border p-3 text-[10px] text-muted-foreground">{result.scope_boundary}</p>}</div>;
  return <div className="space-y-5"><ObjectRows title="System events" rows={data.events} lang={lang} technical/><ObjectRows title="Agent runs" rows={data.agent_tasks} lang={lang} technical/><ObjectRows title="Direct merchant incidents" rows={data.direct_merchant_incidents} lang={lang} technical/><ObjectRows title="Integration events" rows={data.integrations} lang={lang} technical/>{result.incident_coverage?.reason&&<p className="rounded-xl border border-amber-500/25 p-3 text-[10px] text-muted-foreground">{result.incident_coverage.reason}</p>}</div>;
}

function MerchantBlock({definition,row,cache,open,setOpen,loadBlock,onAsk,lang,t}) {
  const [key,english]=definition;const item=cache[`${row.id}:${key}`];const title=BLOCK_TRANSLATIONS[lang]?.[key]||english;
  const toggle=()=>{const next=!open;setOpen(next);if(next&&!item)loadBlock(row.id,key)};
  return <article className="rounded-xl border bg-card"><button onClick={toggle} aria-expanded={open} className="flex w-full items-center gap-3 p-4 text-left"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-xs font-black">{title}</p>{item?.data?.status&&<TruthBadge value={item.data.status}/>}</div><p className="mt-1 truncate text-[10px] text-muted-foreground">{item?.data?.summary||blockMini(row,key,lang,t)}</p></div><ChevronDown size={14} className={`transition ${open?"rotate-180":""}`}/></button>{open&&<div className="border-t p-4">{item?.loading?<Loading label={t("loading_detail")}/>:item?.error?<ErrorNotice error={item.error} onRetry={()=>loadBlock(row.id,key,true)} t={t}/>:item?.data?<><BlockContent block={key} result={item.data} row={row} lang={lang} t={t}/><DependencyStrip rows={item.data.dependencies} t={t}/><div className="mt-4 flex justify-end"><button onClick={()=>onAsk({context_level:"MERCHANT",merchant_id:row.id,block:key},`${row.trading_name} · ${title}`,["Explain this","What changed this week?","What should I do next?"])} className="inline-flex h-9 items-center gap-1.5 rounded-lg border px-3 text-xs font-bold"><Bot size={13}/>{t("ask")}</button></div></>:null}</div>}</article>;
}

function MerchantRow({row,selected,onSelect,expanded,onToggle,blockCache,loadBlock,onAsk,lang,t}) {
  const [openBlocks,setOpenBlocks]=useState({});
  return <article id={`merchant-${row.id}`} className={`overflow-hidden rounded-2xl border bg-card transition ${expanded?"border-foreground/30 shadow-sm":"border-border/60"}`}><div className="flex flex-col gap-3 p-4 sm:flex-row sm:items-center"><button aria-label={`Select ${row.trading_name}`} onClick={onSelect} className={`grid h-5 w-5 shrink-0 place-items-center rounded border ${selected?"bg-foreground text-background":"bg-background"}`}>{selected&&<Check size={13}/>}</button><button onClick={onToggle} className="min-w-0 flex-1 text-left"><p className="truncate text-sm font-black">{row.trading_name}</p><p className="mt-1 truncate text-[10px] text-muted-foreground"><i>{row.legal_name||"Legal name unavailable"}</i> · {flag(row.country)} {row.country||t("unknown")} · <span className="font-bold">{humanize(row.merchant_status)}</span></p></button><button onClick={onToggle} className="flex items-center justify-between gap-4 text-left sm:min-w-56 sm:justify-end"><div className="sm:text-right"><p className="text-xl font-black">{row.potential_savings?.pct==null?"—":`${numberValue(row.potential_savings.pct,lang)}%`}</p><p className="text-[9px] text-muted-foreground">{row.potential_savings?`${moneyMinor(row.potential_savings.value_minor,"EUR",lang)}${t("per_year")} ${t("potential_savings")}`:t("not_analyzed")}</p></div><ChevronRight size={15} className={`transition ${expanded?"rotate-90":""}`}/></button></div>{expanded&&<div className="border-t bg-secondary/[.08] p-4"><MerchantSummaryMetrics row={row} lang={lang}/><div className="mt-4 flex justify-end"><button onClick={()=>onAsk({context_level:"MERCHANT",merchant_id:row.id,block:"overview"},row.trading_name,["Explain this merchant to me.","Why is potential saving high?","What is blocking Recover?","What should I do next?"])} className="inline-flex h-9 items-center gap-1.5 rounded-lg border bg-card px-3 text-xs font-bold"><Bot size={13}/>{t("ask")}</button></div>{["merchant_performance","cambra_operations","administration_audit"].map(group=><section key={group} className="mt-5"><p className="mb-2 text-[9px] font-black uppercase tracking-[.15em] text-muted-foreground">{t(group)}</p><div className="space-y-2">{BLOCKS.filter(definition=>definition[2]===group).map(definition=><MerchantBlock key={definition[0]} definition={definition} row={row} cache={blockCache} open={Boolean(openBlocks[definition[0]])} setOpen={value=>setOpenBlocks(current=>({...current,[definition[0]]:value}))} loadBlock={loadBlock} onAsk={onAsk} lang={lang} t={t}/>)}</div></section>)}</div>}</article>;
}

function CompareModal({rows,onClose,lang,t}) {
  if(!rows)return null;
  const metrics=[
    {label:"Status",getValue:row=>humanize(row.merchant_status)},{label:"Country",getValue:row=>`${flag(row.country)} ${row.country||"—"}`},
    {label:"Payment Volume",getValue:row=>moneyMinor(row.payment_volume?.value_minor,"EUR",lang)},
    {label:"Payment Cost",getValue:row=>row.payment_cost?`${numberValue(row.payment_cost.bps/100,lang)}%`:"—"},
    {label:"Potential Savings",getValue:row=>row.potential_savings?`${numberValue(row.potential_savings.pct,lang)}% · ${moneyMinor(row.potential_savings.value_minor,"EUR",lang)}`:"—"},
    {label:"Verified Savings",getValue:row=>row.evidence?.source_coverage?.verified_savings==="UNAVAILABLE"?t("unavailable"):moneyMinor(row.verified_savings?.value_minor,"EUR",lang)},
    {label:"CAMBRA Revenue",getValue:row=>row.evidence?.source_coverage?.cambra_revenue==="UNAVAILABLE"?t("unavailable"):moneyMinor(row.cambra_revenue?.collected_minor,"EUR",lang)},
    {label:"Data Confidence",getValue:row=>row.data_confidence==null?"—":`${numberValue(row.data_confidence,lang)}%`},
    {label:"Recover",getValue:row=>humanize(row.recover?.status)},{label:"Needs Attention",getValue:row=>row.needs_attention==null?t("unavailable"):numberValue(row.needs_attention,lang)},
  ];
  return <div className="fixed inset-0 z-[100] bg-black/35 p-3 backdrop-blur-sm" onClick={onClose}><div className="mx-auto mt-[5vh] max-h-[90vh] max-w-6xl overflow-auto rounded-3xl border bg-card shadow-2xl" onClick={event=>event.stopPropagation()}><header className="sticky top-0 z-10 flex items-center justify-between border-b bg-card p-5"><div><p className="flex items-center gap-2 text-base font-black"><Columns3 size={17}/>{t("comparison")}</p><p className="mt-1 text-[10px] text-muted-foreground">Read-only · canonical values only</p></div><button onClick={onClose} className="rounded-full border p-2"><X size={14}/></button></header><div className="overflow-x-auto p-5"><table className="w-full min-w-[760px] text-left text-xs"><thead><tr className="border-b"><th className="p-3 text-[9px] uppercase text-muted-foreground">Metric</th>{rows.map(row=><th key={row.id} className="p-3"><p className="font-black">{row.trading_name}</p><p className="mt-1 text-[9px] font-normal text-muted-foreground">{row.legal_name||"—"}</p></th>)}</tr></thead><tbody>{metrics.map(({label,getValue})=><tr key={label} className="border-b border-border/50"><th className="p-3 text-[9px] uppercase text-muted-foreground">{label}</th>{rows.map(row=><td key={row.id} className="p-3 font-semibold">{getValue(row)}</td>)}</tr>)}</tbody></table><p className="mt-4 text-[9px] text-muted-foreground">{t("truth_note")} {t("unknown_values_last")}</p></div></div></div>;
}

function chunk(rows,size) { const result=[];for(let index=0;index<rows.length;index+=size)result.push(rows.slice(index,index+size));return result; }

export default function AdminMerchants() {
  const {lang:rawLang}=useTranslation();const lang=["en","fr","es"].includes(rawLang)?rawLang:"en";
  const t=useCallback((key,params)=>interpolate(MERCHANTS_V2_COPY[lang]?.[key]??MERCHANTS_V2_COPY.en[key]??key,params),[lang]);
  const [portfolio,setPortfolio]=useState(null),[rows,setRows]=useState([]),[loading,setLoading]=useState(true),[loadingMore,setLoadingMore]=useState(false),[error,setError]=useState("");
  const [search,setSearch]=useState(""),[filters,setFilters]=useState(EMPTY_FILTERS),[sortBy,setSortBy]=useState("potential_savings"),[sortDirection,setSortDirection]=useState("desc"),[filtersOpen,setFiltersOpen]=useState(false);
  const [quickView,setQuickView]=useState("all"),[selected,setSelected]=useState(new Set()),[expanded,setExpanded]=useState(null),[pendingExpand,setPendingExpand]=useState(null);
  const [openKpi,setOpenKpi]=useState(null),[kpiDetails,setKpiDetails]=useState({}),[blockCache,setBlockCache]=useState({}),[comparison,setComparison]=useState(null);
  const [askState,setAskState]=useState({open:false,context:{context_level:"SEGMENT"},label:"Portfolio",suggestions:[],prompt:""});
  const [saveOpen,setSaveOpen]=useState(false),[saveName,setSaveName]=useState(""),[notice,setNotice]=useState("");
  const requestRef=useRef(0);
  const query=useMemo(()=>({search:search.trim(),filters,sort_by:sortBy,sort_direction:sortDirection,page_size:25}),[search,filters,sortBy,sortDirection]);
  const querySignature=useMemo(()=>JSON.stringify(query),[query]);

  const loadPortfolio=useCallback(async()=>{const serial=++requestRef.current;setLoading(true);setError("");try{const data=await callMerchants("portfolio",query);if(serial!==requestRef.current)return;setPortfolio(data);setRows(data.merchants?.items||[]);setKpiDetails({});setOpenKpi(null);setSelected(new Set())}catch(cause){if(serial===requestRef.current)setError(cause?.message||"merchant_portfolio_unavailable")}finally{if(serial===requestRef.current)setLoading(false)}},[querySignature]);
  useEffect(()=>{const timer=setTimeout(loadPortfolio,search.trim()?250:0);return()=>clearTimeout(timer)},[loadPortfolio,search]);

  useEffect(()=>{if(!pendingExpand||!rows.some(row=>row.id===pendingExpand))return;setExpanded(pendingExpand);setPendingExpand(null);requestAnimationFrame(()=>document.getElementById(`merchant-${pendingExpand}`)?.scrollIntoView({behavior:"smooth",block:"center"}))},[pendingExpand,rows]);
  const loadMore=async()=>{const cursor=portfolio?.merchants?.next_cursor;if(!cursor||loadingMore)return;setLoadingMore(true);setError("");try{const data=await callMerchants("list",{...query,cursor});setRows(current=>[...current,...(data.merchants?.items||[])]);setPortfolio(current=>({...current,...data,merchants:{...data.merchants,items:[...current.merchants.items,...(data.merchants?.items||[])]}}))}catch(cause){setError(cause?.message||"merchant_page_unavailable")}finally{setLoadingMore(false)}};
  const loadKpi=async(key)=>{if(kpiDetails[key])return;setKpiDetails(current=>({...current,[key]:{loading:true}}));try{const data=await callMerchants("kpi_detail",{...query,kpi_key:key});setKpiDetails(current=>({...current,[key]:{data}}))}catch(cause){setKpiDetails(current=>({...current,[key]:{error:cause?.message||"kpi_detail_unavailable"}}))}};
  const toggleKpi=key=>{const next=openKpi===key?null:key;setOpenKpi(next);if(next)loadKpi(next)};
  const loadBlock=async(merchantId,block,force=false)=>{const cacheKey=`${merchantId}:${block}`;if(blockCache[cacheKey]&&!force)return;setBlockCache(current=>({...current,[cacheKey]:{loading:true}}));try{const data=await callMerchants("merchant_block",{merchant_id:merchantId,block});setBlockCache(current=>({...current,[cacheKey]:{data}}))}catch(cause){setBlockCache(current=>({...current,[cacheKey]:{error:cause?.message||"merchant_block_unavailable"}}))}};
  const onAsk=(context,label,suggestions=[],prompt="")=>setAskState({open:true,context:{...query,...context},label,suggestions,prompt});
  const exportCurrent=async()=>{setError("");try{const data=await callMerchants("export",query);const blob=new Blob([data.content||""],{type:"text/csv;charset=utf-8"});const href=URL.createObjectURL(blob);const anchor=document.createElement("a");anchor.href=href;anchor.download=data.filename||"cambra-merchants.csv";anchor.click();URL.revokeObjectURL(href);setNotice(data.truncated?`${t("export_ready")} · ${data.row_count}/${data.max_rows}`:t("export_ready"))}catch(cause){setError(cause?.message||"merchant_export_unavailable")}};
  const compareSelected=async()=>{if(selected.size<2||selected.size>5){setError("compare_requires_2_to_5_merchants");return}setError("");try{const data=await callMerchants("compare",{merchant_ids:[...selected]});setComparison(data.comparison||[])}catch(cause){setError(cause?.message||"merchant_compare_unavailable")}};
  const saveView=async()=>{if(!saveName.trim())return;try{await callMerchants("save_view",{name:saveName.trim(),filters,sort_by:sortBy,sort_direction:sortDirection});setSaveName("");setSaveOpen(false);setNotice(t("saved"));loadPortfolio()}catch(cause){setError(cause?.message||"save_view_failed")}};
  const deleteView=async(id)=>{try{await callMerchants("delete_view",{saved_view_id:id});setNotice(t("deleted"));loadPortfolio()}catch(cause){setError(cause?.message||"delete_view_failed")}};
  const applyView=view=>{setSearch("");setFilters(view.filters||{});setSortBy(view.sort_by||"potential_savings");setSortDirection(view.sort_direction||"desc");setQuickView(view.key||view.id||"custom")};
  const openMerchant=id=>{if(rows.some(row=>row.id===id)){setExpanded(id);requestAnimationFrame(()=>document.getElementById(`merchant-${id}`)?.scrollIntoView({behavior:"smooth",block:"center"}));return}setSearch(id);setFilters({});setPendingExpand(id)};
  const sourceLimited=portfolio?.source_health?.some(source=>source.status!=="AVAILABLE");
  const kpiRows=chunk(portfolio?.kpis||[],3);

  return <div className="space-y-6 pb-20"><header className="rounded-3xl border bg-card p-5 shadow-sm"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-foreground text-background"><Building2 size={18}/></div><div><h1 className="text-2xl font-black tracking-tight">{t("title")}</h1><p className="mt-1 max-w-2xl text-[11px] text-muted-foreground">{t("subtitle")}</p></div></div><div className="flex flex-wrap gap-2"><button onClick={loadPortfolio} disabled={loading} className="inline-flex h-9 items-center gap-1.5 rounded-lg border px-3 text-xs font-bold"><RefreshCw size={13} className={loading?"animate-spin":""}/>{t("refresh")}</button><button onClick={()=>onAsk({context_level:"SEGMENT"},"Portfolio",["Show me the best merchants this week.","Find anomalies","What needs my attention?","Compare countries"])} className="inline-flex h-9 items-center gap-1.5 rounded-lg bg-foreground px-3 text-xs font-bold text-background"><Bot size={13}/>{t("ask")}</button></div></div>{portfolio&&<div className={`mt-4 flex items-center gap-2 rounded-xl border p-3 text-[10px] ${sourceLimited?"border-amber-500/25 bg-amber-500/[.05] text-amber-600":"border-emerald-500/20 bg-emerald-500/[.04] text-emerald-600"}`}>{sourceLimited?<AlertTriangle size={13}/>:<ShieldCheck size={13}/>}<span><b>{t("source_health")}:</b> {sourceLimited?t("source_limits"):t("sources_healthy")}</span></div>}</header>

  <ErrorNotice error={error} onRetry={loadPortfolio} t={t}/>{notice&&<div className="flex items-center gap-2 rounded-xl border border-emerald-500/20 bg-emerald-500/[.04] p-3 text-xs text-emerald-600"><Check size={13}/>{notice}<button onClick={()=>setNotice("")} className="ml-auto"><X size={12}/></button></div>}

  {loading&&!portfolio?<Loading label={t("loading")}/>:portfolio&&<>
    <section aria-label="Portfolio KPI Intelligence" className="space-y-3">{kpiRows.map((kpis,rowIndex)=><div key={rowIndex} className="grid grid-cols-1 gap-3 md:grid-cols-3">{kpis.map(kpi=><KpiCard key={kpi.key} kpi={kpi} open={openKpi===kpi.key} onClick={()=>toggleKpi(kpi.key)} lang={lang}/>)}{kpis.some(kpi=>kpi.key===openKpi)&&<KpiDrilldown detail={kpiDetails[openKpi]?.data} loading={kpiDetails[openKpi]?.loading} error={kpiDetails[openKpi]?.error} kpi={kpis.find(kpi=>kpi.key===openKpi)} t={t} lang={lang} onAsk={onAsk} onOpenMerchant={openMerchant} onExport={exportCurrent}/>}</div>)}</section>

    <section className="space-y-3"><div className="rounded-2xl border bg-card p-4"><div className="flex flex-col gap-3 lg:flex-row"><label className="relative min-w-0 flex-1"><Search size={14} className="absolute left-3 top-3 text-muted-foreground"/><input value={search} onChange={event=>{setSearch(event.target.value);setQuickView("custom")}} placeholder={t("search")} className="h-10 w-full rounded-xl border bg-background pl-9 pr-3 text-xs outline-none focus:ring-2 focus:ring-foreground/10"/></label><button onClick={()=>setFiltersOpen(value=>!value)} className={`inline-flex h-10 items-center justify-center gap-1.5 rounded-xl border px-3 text-xs font-bold ${filtersOpen?"bg-foreground text-background":""}`}><Filter size={13}/>{filtersOpen?t("hide_filters"):t("filters")} {Object.keys(filters).length>0&&<span className="rounded-full bg-background/20 px-1.5">{Object.keys(filters).length}</span>}</button><label className="flex h-10 items-center gap-2 rounded-xl border px-3 text-xs"><span className="text-muted-foreground">{t("sort")}</span><select value={sortBy} onChange={event=>setSortBy(event.target.value)} className="min-w-32 bg-transparent font-bold outline-none">{SORTS.map(key=><option key={key} value={key}>{humanize(key)}</option>)}</select></label><button title={t("direction")} onClick={()=>setSortDirection(value=>value==="desc"?"asc":"desc")} className="grid h-10 w-10 place-items-center rounded-xl border">{sortDirection==="desc"?<ArrowDown size={14}/>:<ArrowUp size={14}/>}</button></div><div className="mt-3 flex flex-wrap items-center gap-2">{(portfolio.quick_views||[]).map(view=><button key={view.key} onClick={()=>applyView(view)} className={`rounded-full px-3 py-1.5 text-[10px] font-bold ${quickView===view.key?"bg-foreground text-background":"border"}`}>{t(view.key)}</button>)}<span className="mx-1 h-4 w-px bg-border"/>{(portfolio.saved_views||[]).map(view=><div key={view.id} className="inline-flex overflow-hidden rounded-full border"><button onClick={()=>applyView(view)} className="px-3 py-1.5 text-[10px] font-bold">{view.name}</button><button aria-label={`${t("delete")} ${view.name}`} onClick={()=>deleteView(view.id)} className="border-l px-2 text-muted-foreground hover:text-rose-500"><Trash2 size={11}/></button></div>)}<button onClick={()=>setSaveOpen(value=>!value)} className="inline-flex items-center gap-1.5 rounded-full border px-3 py-1.5 text-[10px] font-bold"><Save size={11}/>{t("save_view")}</button></div>{saveOpen&&<div className="mt-3 flex max-w-md gap-2"><input value={saveName} onChange={event=>setSaveName(event.target.value)} onKeyDown={event=>event.key==="Enter"&&saveView()} placeholder={t("view_name")} className="h-9 min-w-0 flex-1 rounded-lg border bg-background px-3 text-xs"/><button disabled={!saveName.trim()} onClick={saveView} className="rounded-lg bg-foreground px-3 text-[10px] font-bold text-background disabled:opacity-40">{t("save_view")}</button></div>}</div>{filtersOpen&&<FilterPanel options={portfolio.filters} filters={filters} setFilters={value=>{setFilters(value);setQuickView("custom")}} t={t}/>}</section>

    <section className="space-y-3"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-base font-black">{t("title")}</h2><p className="mt-1 text-[10px] text-muted-foreground">{t("result_count",{shown:rows.length,total:portfolio.merchants?.total||0})} · {t("truth_note")}</p></div><div className="flex flex-wrap gap-2">{selected.size>0&&<button onClick={()=>setSelected(new Set())} className="rounded-lg border px-3 py-2 text-[10px] font-bold">{selected.size} {t("selected")} · {t("clear")}</button>}<button onClick={compareSelected} disabled={selected.size<2||selected.size>5} className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-[10px] font-bold disabled:opacity-35"><Columns3 size={12}/>{t("compare")} {selected.size?`(${selected.size})`:""}</button><button onClick={exportCurrent} className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-[10px] font-bold"><ArrowDownToLine size={12}/>{t("export")}</button><button onClick={()=>onAsk({context_level:"SEGMENT",merchant_ids:[...selected]},selected.size?`${selected.size} selected`:"Current segment",["Show the best merchants","Explain this segment","Find anomalies","What should I do?"])} className="inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-[10px] font-bold"><Bot size={12}/>{t("ask")}</button></div></div>{rows.length?<div className="space-y-3">{rows.map(row=><MerchantRow key={row.id} row={row} selected={selected.has(row.id)} onSelect={()=>setSelected(current=>{const next=new Set(current);if(next.has(row.id))next.delete(row.id);else if(next.size<5)next.add(row.id);return next})} expanded={expanded===row.id} onToggle={()=>setExpanded(expanded===row.id?null:row.id)} blockCache={blockCache} loadBlock={loadBlock} onAsk={onAsk} lang={lang} t={t}/>)}</div>:<div className="rounded-2xl border border-dashed p-12 text-center"><Database className="mx-auto text-muted-foreground"/><p className="mt-3 text-sm font-black">{t("no_merchants")}</p><p className="mx-auto mt-1 max-w-xl text-xs text-muted-foreground">{t("no_merchants_body")}</p><button onClick={()=>{setSearch("");setFilters({});setQuickView("all")}} className="mt-4 rounded-lg border px-3 py-2 text-xs font-bold">{t("clear")}</button></div>}{portfolio.merchants?.next_cursor&&<div className="flex justify-center pt-2"><button disabled={loadingMore} onClick={loadMore} className="inline-flex h-10 items-center gap-2 rounded-xl border px-5 text-xs font-bold">{loadingMore?<Loader2 size={13} className="animate-spin"/>:<ChevronDown size={13}/>} {t("load_more")}</button></div>}</section>
  </>}
  <AskCambraDrawer state={askState} setState={setAskState} t={t}/><CompareModal rows={comparison} onClose={()=>setComparison(null)} lang={lang} t={t}/></div>;
}
